	public boolean canPlaceSettlement(Player player, GameState gameState) {
		if (structure != null) {
			return false;
		}

		if (gameState == GameState.SETUP) {
			return distanceRule();
		}

		boolean connectedRoad = false;
		for (Edge edge : edges) {
			if (edge.hasRoad() && edge.getRoad().getOwner().equals(player)) {
				connectedRoad = true;
			}
		}

		if (!connectedRoad) {
			return false;
		}

		// Distance rule
		return distanceRule();
	}

	public boolean distanceRule() {
		boolean distanceRule = true;
		for (Edge edge : edges) {
			Node otherNode;
			if (edge.getStartNode().equals(this)) {
				otherNode = edge.getEndNode();
			} else {
				otherNode = edge.getStartNode();
			}

			if (otherNode.hasStructure()) {
				distanceRule = false;
			}
		}

		return distanceRule;
	}

	public boolean canPlaceCity(Player player, GameState gameState) {
		if (structure == null || gameState != GameState.PLAYING) {
			return false;
		}

		if (structure instanceof Settlement && structure.getOwner().equals(player)) {
			return true;
		}

		return false;
	}

